begin;
select no_plan();
create function pg_temp.bundle() returns jsonb language sql as $$select $fixture${"schema":"gina.library-import.v1","package_key":"test-library-intake","revision":1,"previous_hash":null,"title":"Test import package","grade":5,"subject":"Matematik","provenance":{"locale":"tr","curriculum_reference":{"programme_url":"https://tymm.meb.gov.tr/ortaokul-matematik-dersi/unite/448?kod=MAB3","programme_page_updated":"2026-09-04","checked_on":"2026-11-03","distribution_index":"https://odsgm.meb.gov.tr/www/1donem-konu-soru-dagilim-tablolari-2026-2027/icerik/1724","candidate_scenario_id":"tr-2026-2027-t1-ilkmat2-g5-d6","candidate_source_sha256":"d5429b5962a08adc04acd71ceaae2d517bca507f8b4cf94354bcd55a9670aebf","mapping_status":"proposed_pending_subject_review"},"programme_version":"2026-09-04 web programme; implementation/school applicability pending review","school_track_applicability":"pending_review","assessment_notes":["20 items form a pool, not a 20-question compulsory session or an official school exam.","Questions sharing a source are related observations; do not count them as independent evidence of mastery.","All difficulty labels are estimates; no empirical calibration or official approval.","Schematic drawing/description does not certify compass, ruler or protractor manipulation.","Do not grade drawing neatness, motor control, gender, handwriting style or response speed."],"private_note":"PRIVATE_PROVENANCE_SECRET"},"assets":[{"key":"segments","mime":"image/png","sha256":"890c8dc04fe5952ec0d0af6efac019b10bb3287d116b22adcca2e1bd5effdeb8","width":1,"height":1,"base64":"iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAIAAACQd1PeAAAADElEQVR4nGNwcHAAAAGEAMGDX2mUAAAAAElFTkSuQmCC"}],"sources":[{"key":"segments","title":"İki çizim","body":"A ve B arasında iki ucu noktayla gösterilmiş bir çizim; C noktasından başlayıp D üzerinden sağa doğru devam eden, ucunda ok bulunan başka bir çizim var.","alt":"AB çiziminde iki uç nokta var. CD çiziminde başlangıç C; D üzerinden sağa uzanan ok var.","asset_key":"segments","minimum_reading_width":0,"provenance":{"origin":"original_gina_mathematical_diagram","svg_sha256":"a7465f14b876c2ac11a84384c0082f5d16d5fee29cd75b927b8b3c2a1882709b","color_space":"sRGB"}}],"questions":[{"key":"gina-g5-math-geometry-01","revision":1,"source_key":"segments","student":{"grade":5,"subject":"Matematik","topic":"Geometrik şekiller","kind":"open_ended","difficulty":"kolay","stem":"AB ve CD çizimlerinin geometrik adlarını yaz. Uç noktaları ve devam yönleri bakımından aralarındaki farkı açıkla.","choices":[]},"teacher":{"correct_key":null,"expected_answer":"TEACHER_ANSWER_SECRET","solution":"İki uçta nokta bulunan AB sınırlıdır. CD’de başlangıç C ve devamı gösteren bir ok vardır.","explanation":"Nokta ile ok işaretlerini karşılaştır; bir çizimin devam edip etmediğine onlar karar verir.","rubric":{"max_points":4,"scoring":"Her ölçüt ayrı değerlendirilir. Listelenen alt koşullar tamamlanınca o ölçütün puanı verilir; diğer ölçütler bundan bağımsızdır. Eşdeğer gerekçe ve gösterimler kabul edilir.","criteria":[{"id":"c1","points":1,"criterion":"AB’yi doğru parçası olarak adlandırır."},{"id":"c2","points":1,"criterion":"CD’yi ışın olarak adlandırır."},{"id":"c3","points":1,"criterion":"AB’nin iki uç noktayla sınırlı olduğunu belirtir."},{"id":"c4","points":1,"criterion":"CD’nin C’den başlayıp D yönünde devam ettiğini belirtir."}],"missing_answer":"not_answered; eksik öğrenme veya sıfır yeterlilik sonucu çıkarma","review_required":true},"common_misconception":"Ok ucunu ikinci uç nokta sanmak.","next_step":"Nokta ile ok işaretlerini karşılaştır; bir çizimin devam edip etmediğine onlar karar verir."},"metadata":{"curriculum":{"candidate_code":"MAT.5.3.2","mapping_status":"proposed_pending_subject_review","evidence_scope":"reasoning"},"response":{"mode":"text_or_drawing","precise_screen_measurement_required":false,"required_tools":[],"accommodation":"Metin veya anlamı açık etiketli çizim kabul edilir; yazı güzelliği puanlanmaz."},"evidence_unit":"segments","depends_on_question_ids":[],"provenance":{"authoring":"Codex-authored original draft, not copied from an exam","created_on":"2026-11-03","paid_provider_call":false},"difficulty_calibration":"editorial_estimate_not_empirical","private_note":"PRIVATE_METADATA_SECRET"}},{"key":"gina-g5-math-geometry-02","revision":1,"source_key":"segments","student":{"grade":5,"subject":"Matematik","topic":"Geometrik şekiller","kind":"open_ended","difficulty":"orta","stem":"Defterinde E ve F adlı iki farklı nokta göster. E’den başlayıp F yönünde devam eden bir ışını şematik çiz veya nasıl çizileceğini tarif et. Düz çizgiyi oluşturmak için hangi aracı seçerdin? Neden?","choices":[]},"teacher":{"correct_key":null,"expected_answer":"E başlangıçtır; çizgi F’den geçer ve F yönünde bir okla devam eder. Düz çizgi için cetvel/çizgeç veya dijital ışın aracı seçilir.","solution":"E ve F işaretlenir. Cetvel iki noktaya hizalanır. E’den başlayıp F’den geçen çizgi F yönüne uzatılır; devam yönü okla gösterilir.","explanation":"Işının başlangıcını ve devam yönünü ayrı işaretle. Ekranda kusursuz düz çizmek gerekmiyor.","rubric":{"max_points":4,"scoring":"Her ölçüt ayrı değerlendirilir. Listelenen alt koşullar tamamlanınca o ölçütün puanı verilir; diğer ölçütler bundan bağımsızdır. Eşdeğer gerekçe ve gösterimler kabul edilir.","criteria":[{"id":"c1","points":1,"criterion":"E başlangıç noktasını doğru belirler."},{"id":"c2","points":1,"criterion":"Çizgi veya tarif F’den geçer."},{"id":"c3","points":1,"criterion":"Devam yönünü F yönündeki okla veya eşdeğer sözle gösterir."},{"id":"c4","points":1,"criterion":"Cetvel/çizgeç/dijital ışın aracını düz çizgi oluşturma gerekçesiyle seçer."}],"missing_answer":"not_answered; eksik öğrenme veya sıfır yeterlilik sonucu çıkarma","review_required":true},"common_misconception":"E’nin gerisine de ok ekleyerek ışını doğruya çevirmek.","next_step":"Işının başlangıcını ve devam yönünü ayrı işaretle. Ekranda kusursuz düz çizmek gerekmiyor."},"metadata":{"curriculum":{"candidate_code":"MAT.5.3.1","mapping_status":"proposed_pending_subject_review","evidence_scope":"tool_selection_and_schematic_representation_not_instrument_performance"},"response":{"mode":"drawing_or_description","precise_screen_measurement_required":false,"required_tools":[],"accommodation":"Kalem zorunlu değildir. Çizim istenen soruda şeklin uçlarını, ok yönünü ve bağlantılarını yazıyla açıkça tarif etmek de kabul edilir. Bu alternatif gerçek araç kullanma becerisi kanıtı sayılmaz."},"evidence_unit":"question-02","depends_on_question_ids":[],"provenance":{"authoring":"Codex-authored original draft, not copied from an exam","created_on":"2026-11-03","paid_provider_call":false},"difficulty_calibration":"editorial_estimate_not_empirical"}}]}$fixture$::jsonb$$;
insert into auth.users(id,email) values
('00000000-0000-4000-8000-000000004001','library-intake-admin@test.local'),
('00000000-0000-4000-8000-000000004002','library-intake-parent@test.local'),
('00000000-0000-4000-8000-000000004003','library-intake-admin2@test.local');
insert into public.admins(user_id) values('00000000-0000-4000-8000-000000004001'),('00000000-0000-4000-8000-000000004003');
create temp table intake_result(result jsonb);grant all on intake_result to authenticated;
create temp table intake_baseline as select (select count(*) from public.library_items) items,(select count(*) from public.library_redemptions) redemptions,(select count(*) from gina.library_import_assets) assets;
set local role anon;
select throws_ok($$select public.admin_import_library_bundle(gen_random_uuid(),pg_temp.bundle())$$,'42501',null,'anonymous caller has no import grant');
reset role;set local role service_role;
select throws_ok($$select public.admin_import_library_bundle(gen_random_uuid(),pg_temp.bundle())$$,'42501',null,'service credential is not an editorial identity');
reset role;set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000004002","gina":{"role":"parent"}}',true);
select throws_ok($$select public.admin_import_library_bundle(gen_random_uuid(),pg_temp.bundle())$$,'42501','forbidden','parent cannot stage paid teacher content');
select throws_ok($$select public.admin_list_library_imports()$$,'42501','forbidden','parent cannot list drafts');
select throws_ok($$select public.admin_get_library_import(gen_random_uuid(),false)$$,'42501','forbidden','even draft student projection is admin-only');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000004002","gina":{"role":"device","admin":true}}',true);
select throws_ok($$select public.admin_import_library_bundle(gen_random_uuid(),pg_temp.bundle())$$,'42501','forbidden','forged or stale admin claim without membership denied');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000004001","gina":{"role":"none","admin":true}}',true);
select throws_ok($$select public.admin_import_library_bundle(null,pg_temp.bundle())$$,'P0001','library_import_size','request identity required');
select throws_ok($$select public.admin_import_library_bundle(gen_random_uuid(),pg_temp.bundle()||'{"publish":true}')$$,'P0001','library_import_shape','no caller publication flag');
select throws_ok($$select public.admin_import_library_bundle(gen_random_uuid(),jsonb_set(pg_temp.bundle(),'{questions,0,student,expected_answer}','"SECRET"'))$$,'P0001','library_import_shape','answer cannot be hidden in student fields');
select throws_ok($$select public.admin_import_library_bundle(gen_random_uuid(),jsonb_set(pg_temp.bundle(),'{questions,0,student,grade}','6'))$$,'P0001','library_import_scope','grade mismatch rolls back package');
select throws_ok($$select public.admin_import_library_bundle(gen_random_uuid(),jsonb_set(pg_temp.bundle(),'{questions,0,source_key}','"missing"'))$$,'P0001','library_import_missing_source','missing shared source rejected');
select throws_ok($$select public.admin_import_library_bundle(gen_random_uuid(),jsonb_set(pg_temp.bundle(),'{sources,0,asset_key}','"missing"'))$$,'P0001','library_import_missing_asset','missing bytes rejected');
select throws_ok($$select public.admin_import_library_bundle(gen_random_uuid(),jsonb_set(pg_temp.bundle(),'{assets,0,sha256}',to_jsonb(repeat('0',64))))$$,'P0001','library_import_asset','actual asset checksum verified');
select throws_ok($$select public.admin_import_library_bundle(gen_random_uuid(),jsonb_set(pg_temp.bundle(),'{assets,0,mime}','"image/svg+xml"'))$$,'P0001','library_import_asset','active SVG is not accepted as rendered bytes');
select throws_ok($$select public.admin_import_library_bundle(gen_random_uuid(),jsonb_set(pg_temp.bundle(),'{assets,0,base64}','"PHN2Zz4="'))$$,'P0001','library_import_png','SVG bytes disguised as PNG rejected');
select throws_ok($$select public.admin_import_library_bundle(gen_random_uuid(),jsonb_set(pg_temp.bundle(),'{assets,0,width}','300'))$$,'P0001','library_import_asset','declared dimensions must match image');
select throws_ok($$select public.admin_import_library_bundle(gen_random_uuid(),jsonb_set(pg_temp.bundle(),'{assets,0,base64}',to_jsonb(replace(encode(decode(pg_temp.bundle()#>>'{assets,0,base64}','base64')||decode('0000','hex'),'base64'),E'\n',''))))$$,'P0001','library_import_png','trailing bytes after IEND rejected');
select throws_ok($$select public.admin_import_library_bundle(gen_random_uuid(),jsonb_set(pg_temp.bundle(),'{assets,0,base64}',to_jsonb(replace(encode(set_byte(set_byte(decode(pg_temp.bundle()#>>'{assets,0,base64}','base64'),18,32),19,0),'base64'),E'\n',''))))$$,'P0001','library_import_png','oversized decoded dimensions rejected before image use');
select throws_ok($$select public.admin_import_library_bundle(gen_random_uuid(),pg_temp.bundle()||jsonb_build_object('provenance',jsonb_build_object('oversize',repeat('x',6000001))))$$,'P0001','library_import_size','overall request byte cap enforced');

select throws_ok($$select public.admin_import_library_bundle(gen_random_uuid(),jsonb_set(pg_temp.bundle(),'{questions,0,teacher,rubric,max_points}','5'))$$,'P0001','library_import_rubric','partial scoring must sum to total');
select throws_ok($$select public.admin_import_library_bundle(gen_random_uuid(),jsonb_set(pg_temp.bundle(),'{questions,0,teacher,rubric,criteria,0,points}','-1'))$$,'P0001','library_import_number','negative credit rejected');
select throws_ok($$select public.admin_import_library_bundle(gen_random_uuid(),jsonb_set(pg_temp.bundle(),'{questions,1,key}',pg_temp.bundle()#>'{questions,0,key}'))$$,'P0001','library_import_duplicate_key','duplicate question key rejected atomically');
reset role;
select is((select count(*)::int from gina.library_import_packages where package_key='test-library-intake'),0,'all failed packages rolled back');
select is((select count(*) from gina.library_import_assets),(select assets from intake_baseline),'failed imports leave no orphan PNG');
set local role authenticated;
insert into intake_result select public.admin_import_library_bundle('10000000-0000-4000-8000-000000004001',pg_temp.bundle());
select is((select result->>'status' from intake_result),'draft','valid bundle is always draft');
select is(public.admin_import_library_bundle('10000000-0000-4000-8000-000000004001',pg_temp.bundle()),(select result from intake_result),'lost response retry returns exact receipt');
select is(public.admin_import_library_bundle('10000000-0000-4000-8000-000000004002',pg_temp.bundle())->>'id',(select result->>'id' from intake_result),'new request for identical revision returns same package');
select throws_ok($$select public.admin_import_library_bundle('10000000-0000-4000-8000-000000004001',jsonb_set(pg_temp.bundle(),'{title}','"Changed package"'))$$,'P0001','library_import_request_conflict','request id cannot mean changed content');
select throws_ok($$select public.admin_import_library_bundle(gen_random_uuid(),jsonb_set(pg_temp.bundle(),'{title}','"Changed package"'))$$,'P0001','library_import_revision_conflict','same revision is immutable');
select ok((public.admin_get_library_import((select (result->>'id')::uuid from intake_result),false)::text not like '%TEACHER_ANSWER_SECRET%'),'student projection hides answer');
select ok((public.admin_get_library_import((select (result->>'id')::uuid from intake_result),false)::text not like '%PRIVATE_%'),'student projection hides private metadata and provenance');
select ok(not((public.admin_get_library_import((select (result->>'id')::uuid from intake_result),false)->'questions'->0)?'teacher'),'student projection contains no teacher object');
select is(public.admin_get_library_import((select (result->>'id')::uuid from intake_result),true)#>>'{questions,0,teacher,expected_answer}','TEACHER_ANSWER_SECRET','explicit editorial reader retains answers');
select is(public.admin_get_library_import((select (result->>'id')::uuid from intake_result),true)#>'{questions,0,teacher,rubric}',pg_temp.bundle()#>'{questions,0,teacher,rubric}','rubric is lossless');
select is(public.admin_get_library_import((select (result->>'id')::uuid from intake_result),false)#>>'{sources,0,png_base64}',pg_temp.bundle()#>>'{assets,0,base64}','stored bytes return unchanged');
select is(jsonb_array_length(public.admin_get_library_import((select (result->>'id')::uuid from intake_result),false)->'questions'),2,'both questions stored together');
select is(public.admin_get_library_import((select (result->>'id')::uuid from intake_result),false)#>>'{questions,0,source_key}',public.admin_get_library_import((select (result->>'id')::uuid from intake_result),false)#>>'{questions,1,source_key}','shared source identity preserved across questions');
select is(jsonb_array_length(public.admin_get_library_import((select (result->>'id')::uuid from intake_result),false)->'sources'),1,'one shared source, not one copy per question');
select throws_ok($$select public.admin_get_library_import(gen_random_uuid(),true)$$,'P0001','library_import_not_found','unknown version has no fallback to latest');
select throws_ok($$select public.admin_get_library_import((select (result->>'id')::uuid from intake_result),null)$$,'P0001','invalid_input','null answer visibility is rejected');

select throws_ok($$select * from gina.library_import_answers$$,'42501',null,'even admin clients cannot bypass RPC with direct table reads');
select throws_ok($$select public.admin_list_library_imports(1000)$$,'P0001','invalid_input','list cannot be unbounded');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000004003","gina":{"admin":true}}',true);
select throws_ok($$select public.admin_import_library_bundle('10000000-0000-4000-8000-000000004001',pg_temp.bundle())$$,'P0001','library_import_request_conflict','receipt is bound to original actor');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000004001","gina":{"admin":true}}',true);
create temp table intake_v2(payload jsonb);grant all on intake_v2 to authenticated;
insert into intake_v2 select jsonb_set(jsonb_set(jsonb_set(pg_temp.bundle(),'{revision}','2'),'{previous_hash}',result->'content_hash'),'{questions,0,teacher,expected_answer}','"Changed teacher answer"') from intake_result;
select throws_ok($$select public.admin_import_library_bundle(gen_random_uuid(),(select payload from intake_v2))$$,'P0001','library_import_question_revision','changed answer needs question revision');
update intake_v2 set payload=jsonb_set(payload,'{questions,0,revision}','2');
select throws_ok($$select public.admin_import_library_bundle(gen_random_uuid(),jsonb_set((select payload from intake_v2),'{previous_hash}','"stale"'))$$,'P0001','library_import_previous_changed','stale package base rejected');
select lives_ok($$select public.admin_import_library_bundle('10000000-0000-4000-8000-000000004003',(select payload from intake_v2))$$,'new version keeps old answer snapshot');
select is(public.admin_get_library_import((select (result->>'id')::uuid from intake_result),true)#>>'{questions,0,teacher,expected_answer}','TEACHER_ANSWER_SECRET','old snapshot still readable');
create temp table intake_v3(payload jsonb);grant all on intake_v3 to authenticated;
insert into intake_v3 select jsonb_set(jsonb_set(jsonb_set(payload,'{revision}','3'),'{previous_hash}',public.admin_import_library_bundle('10000000-0000-4000-8000-000000004003',payload)->'content_hash'),'{sources,0,body}','"Changed common context"') from intake_v2;
select throws_ok($$select public.admin_import_library_bundle(gen_random_uuid(),(select payload from intake_v3))$$,'P0001','library_import_question_revision','changing shared context requires new question revisions');
update intake_v3 set payload=jsonb_set(payload,'{questions,0,revision}','3');
select throws_ok($$select public.admin_import_library_bundle(gen_random_uuid(),(select payload from intake_v3))$$,'P0001','library_import_question_revision','every dependent question must advance, not only first');
update intake_v3 set payload=jsonb_set(payload,'{questions,1,revision}','2');
select lives_ok($$select public.admin_import_library_bundle('10000000-0000-4000-8000-000000004004',(select payload from intake_v3))$$,'shared context update creates a complete new version');
select is(public.admin_get_library_import((select (result->>'id')::uuid from intake_result),false)#>>'{sources,0,body}',pg_temp.bundle()#>>'{sources,0,body}','previous context remains immutable');

reset role;
select is((select count(*)::int from gina.library_import_packages where package_key='test-library-intake'),3,'exactly three immutable versions');
select throws_ok($$update gina.library_import_answers set teacher='{}' where package_id=(select (result->>'id')::uuid from intake_result)$$,'P0001','library_import_immutable','answer rows cannot be overwritten');
select is((select count(*) from public.library_items),(select items from intake_baseline),'legacy published library unchanged');
select is((select count(*) from public.library_redemptions),(select redemptions from intake_baseline),'no family quota consumed');
select is((select count(*)::int from public.audit_log where action='library_bundle.imported' and actor_id='00000000-0000-4000-8000-000000004001'),3,'one audit per new version, none for retries');
set local role authenticated;
select is(public.admin_get_library_import((select (result->>'id')::uuid from intake_result),true)#>'{sources,0,provenance}',pg_temp.bundle()#>'{sources,0,provenance}','editorial reader keeps source provenance');
select ok(not((public.admin_get_library_import((select (result->>'id')::uuid from intake_result),false)#>'{sources,0}')?'provenance'),'student projection hides source provenance');
create temp table text_intake(payload jsonb, result jsonb);grant all on text_intake to authenticated;
insert into text_intake(payload) select jsonb_set(jsonb_set(pg_temp.bundle()||'{"package_key":"text-only-intake","assets":[]}', '{sources,0,asset_key}','null'),'{sources,0,alt}','""');
select throws_ok($$select public.admin_import_library_bundle(gen_random_uuid(),jsonb_set((select payload from text_intake),'{sources,0,body}','""'))$$,'P0001','library_import_text','shared context cannot have neither text nor image');
select lives_ok($$update text_intake set result=public.admin_import_library_bundle(gen_random_uuid(),payload)$$,'shared text is valid without a forced image');
select is(public.admin_get_library_import((select (result->>'id')::uuid from text_intake),false)#>>'{sources,0,body}',pg_temp.bundle()#>>'{sources,0,body}','text-only shared context survives readback');
select is(public.admin_get_library_import((select (result->>'id')::uuid from text_intake),false)#>'{sources,0,png_base64}','null'::jsonb,'text-only source has no invented image');
create temp table mc_intake(payload jsonb, result jsonb);grant all on mc_intake to authenticated;
insert into mc_intake(payload) select pg_temp.bundle()||jsonb_build_object('package_key','mc-intake','assets','[]'::jsonb,'sources','[]'::jsonb,'questions',jsonb_build_array(
 (pg_temp.bundle()#>'{questions,0}')||jsonb_build_object('source_key',null,'student',(pg_temp.bundle()#>'{questions,0,student}')||'{"kind":"multiple_choice","choices":[{"key":"A","text":"First"},{"key":"B","text":"Second"},{"key":"C","text":"Third"},{"key":"D","text":"Fourth"}]}'::jsonb,'teacher',(pg_temp.bundle()#>'{questions,0,teacher}')||'{"correct_key":"B"}'::jsonb)));
select lives_ok($$update mc_intake set result=public.admin_import_library_bundle(gen_random_uuid(),payload)$$,'standalone multiple choice question is supported');
select is(public.admin_get_library_import((select (result->>'id')::uuid from mc_intake),true)#>>'{questions,0,teacher,correct_key}','B','multiple choice key remains in teacher projection');
reset role;
delete from public.admins where user_id='00000000-0000-4000-8000-000000004001';
set local role authenticated;
select throws_ok($$select public.admin_get_library_import((select (result->>'id')::uuid from intake_result),true)$$,'42501','forbidden','revoked editor loses access immediately');
select throws_ok($$select public.admin_import_library_bundle('10000000-0000-4000-8000-000000004001',pg_temp.bundle())$$,'42501','forbidden','revoked editor cannot replay a prior successful receipt');
reset role;
select lives_ok($$delete from auth.users where id='00000000-0000-4000-8000-000000004001'$$,'editor account deletion not blocked by immutable drafts');
select * from finish();
rollback;
